// --- AUDIO ENGINE ---
        let audioCtx;
        let isAudioInitialized = false;
        // Pentatonic Scale Frequencies (approximate E Minor)
        // High frequencies for top row, mid for home, low for bottom
        const notes = {
            'q': 329.63, 'w': 392.00, 'e': 440.00, 'r': 493.88, 't': 587.33, 'y': 659.25, 'u': 783.99, 'i': 880.00, 'o': 987.77, 'p': 1174.66,
            'a': 164.81, 's': 196.00, 'd': 220.00, 'f': 246.94, 'g': 293.66, 'h': 329.63, 'j': 392.00, 'k': 440.00, 'l': 493.88,
            'z': 82.41, 'x': 98.00, 'c': 110.00, 'v': 123.47, 'b': 146.83, 'n': 164.81, 'm': 196.00
        };
        const particleColors = [
            '#EE6C4D', '#3b82f6', '#10b981', '#f59e0b', '#8b5cf6', '#ec4899', '#ffffff'
        ];
        function initAudio() {
            if (isAudioInitialized) return;
            const AudioContext = window.AudioContext || window.webkitAudioContext;
            audioCtx = new AudioContext();
            // Resume if suspended (browser policy)
            if (audioCtx.state === 'suspended') {
                audioCtx.resume();
            }
            const overlay = document.getElementById('start-overlay');
            overlay.style.opacity = '0';
            setTimeout(() => {
                overlay.style.display = 'none';
                document.getElementById('hidden-input').focus();
            }, 500);
            isAudioInitialized = true;
        }
        function playTone(freq, type = 'sine', duration = 0.5) {
            if (!audioCtx) return;
            const osc = audioCtx.createOscillator();
            const gainNode = audioCtx.createGain();
            osc.type = type;
            osc.frequency.setValueAtTime(freq, audioCtx.currentTime);
            // ADSR Envelope (Attack, Decay, Sustain, Release)
            gainNode.gain.setValueAtTime(0, audioCtx.currentTime);
            gainNode.gain.linearRampToValueAtTime(0.3, audioCtx.currentTime + 0.05); // Attack
            gainNode.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + duration); // Decay
            osc.connect(gainNode);
            gainNode.connect(audioCtx.destination);
            osc.start();
            osc.stop(audioCtx.currentTime + duration);
        }
        function playKick() {
            if (!audioCtx) return;
            const osc = audioCtx.createOscillator();
            const gainNode = audioCtx.createGain();
            osc.type = 'sine';
            osc.frequency.setValueAtTime(150, audioCtx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.5);
            gainNode.gain.setValueAtTime(1, audioCtx.currentTime);
            gainNode.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.5);
            osc.connect(gainNode);
            gainNode.connect(audioCtx.destination);
            osc.start();
            osc.stop(audioCtx.currentTime + 0.5);
        }
        function playSnare() {
            if (!audioCtx) return;
            const bufferSize = audioCtx.sampleRate * 0.5; // 0.5 sec noise
            const buffer = audioCtx.createBuffer(1, bufferSize, audioCtx.sampleRate);
            const data = buffer.getChannelData(0);
            for (let i = 0; i < bufferSize; i++) {
                data[i] = Math.random() * 2 - 1;
            }
            const noise = audioCtx.createBufferSource();
            noise.buffer = buffer;
            const noiseFilter = audioCtx.createBiquadFilter();
            noiseFilter.type = 'highpass';
            noiseFilter.frequency.value = 1000;
            const noiseEnvelope = audioCtx.createGain();
            noiseEnvelope.gain.setValueAtTime(0.5, audioCtx.currentTime);
            noiseEnvelope.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.2);
            noise.connect(noiseFilter);
            noiseFilter.connect(noiseEnvelope);
            noiseEnvelope.connect(audioCtx.destination);
            noise.start();
        }
        // --- VISUAL ENGINE ---
        const inputArea = document.getElementById('hidden-input');
        const visualArea = document.getElementById('visual-output');
        const stage = document.getElementById('stage');
        // Main Interaction Loop
        inputArea.addEventListener('keydown', (e) => {
            if (!isAudioInitialized) return;
            const key = e.key.toLowerCase();
            // Audio Trigger
            if (notes[key]) {
                // Randomize wave type slightly for variety
                const types = ['sine', 'triangle'];
                const type = types[Math.floor(Math.random() * types.length)];
                playTone(notes[key], type, 0.8);
                createParticle(particleColors[Math.floor(Math.random() * particleColors.length)]);
            } else if (e.code === 'Space') {
                playKick();
                createParticle('#EE6C4D', 150);
            } else if (e.code === 'Enter') {
                playSnare();
                createParticle('#ffffff', 200);
            } else if (key === 'backspace') {
                playTone(80, 'sawtooth', 0.2);
                visualArea.lastElementChild?.remove();
                return; // Don't add char
            } else {
                // Symbols/Numbers: High sine blips
                playTone(Math.random() * 800 + 200, 'sine', 0.1);
            }
            // Visual Trigger
            if (e.key.length === 1) { // Only printable chars
                addCharacter(e.key);
            } else if (e.code === 'Enter') {
                addCharacter('\n');
            }
        });
        function addCharacter(char) {
            const span = document.createElement('span');
            if (char === '\n') {
                span.innerHTML = '<br>';
                span.style.width = "100%";
            } else if (char === ' ') {
                span.innerHTML = '&nbsp;';
            } else {
                span.innerText = char;
            }
            span.className = "char-span active";
            // Randomize visual chaos slightly
            const rot = (Math.random() * 10) - 5;
            span.style.display = char === '\n' ? 'block' : 'inline-block';
            if (char !== '\n') span.style.transform = `rotate(${rot}deg) scale(1.2)`;
            visualArea.appendChild(span);
            // Remove active class for animation reset
            setTimeout(() => {
                span.classList.remove('active');
                if (char !== '\n') span.style.transform = `rotate(0deg) scale(1)`;
            }, 100);
            // Auto scroll to bottom
            visualArea.scrollTop = visualArea.scrollHeight;
        }
        function createParticle(color, size = 60) {
            const particle = document.createElement('div');
            particle.className = 'note-particle';
            // We can't track cursor perfectly inside hidden textarea, so we randomize within the stage
            // or bias it towards the bottom where typing usually happens
            const x = Math.random() * 90 + 5;
            const y = Math.random() * 80 + 10;
            particle.style.left = x + '%';
            particle.style.top = y + '%';
            particle.style.width = size + 'px';
            particle.style.height = size + 'px';
            particle.style.background = color;
            particle.style.boxShadow = `0 0 25px ${color}`;
            visualArea.appendChild(particle);
            setTimeout(() => {
                particle.remove();
            }, 800);
        }
        function clearStage() {
            visualArea.innerHTML = '';
            inputArea.value = '';
            inputArea.focus();
            playSnare(); // Feedback sound
        }
        function copyText() {
            const text = visualArea.innerText;
            navigator.clipboard.writeText(text).then(() => {
                const btn = document.getElementById('copy-btn');
                const originalHTML = btn.innerHTML;
                btn.innerHTML = `<span class="text-green-400 font-bold">COPIED!</span>`;
                setTimeout(() => btn.innerHTML = originalHTML, 2000);
            });
        }
        // --- UX HELPERS ---
        // Ensure focus is kept on hidden input when clicking anywhere in stage
        stage.addEventListener('click', (e) => {
            if (e.target.id !== 'hidden-input') {
                inputArea.focus();
            }
        });
        // Prevent spacebar from scrolling page when in focus
        window.addEventListener('keydown', function (e) {
            if (e.code === 'Space' && e.target === document.body) {
                e.preventDefault();
            }
        });
